import { ScrollingModule } from '@angular/cdk/scrolling';
import { CommonModule } from '@angular/common';
import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { ButtonComponent } from '../button/button.component';
import { DoccardComponent } from '../doccard/doccard.component';
import { MyfileService } from '../../services/myfile/myfile.service';
import { clearRecentRes, copyCommonRes, recentfileReq, recentfileRes } from '../../interfaces/myfile.interface';
import { MatMenuModule } from '@angular/material/menu';
import { FileexplorerComponent } from '../myfiles/fileexplorer/fileexplorer.component';
import { EmptyComponent } from '../empty/empty.component';
import { IconComponent } from '../icon/icon.component';
import { toolEvents } from '../../../pdf/interfaces/pdf.interface';
import { presentSetupData } from '../../../presentation/interfaces/presentsetup';

@Component({
  selector: 'recentfiles',
  standalone: true,
  imports: [CommonModule, ScrollingModule, ButtonComponent, DoccardComponent, MatMenuModule, EmptyComponent, IconComponent],
  templateUrl: './recentfile.component.html',
  styleUrl: './recentfile.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class RecentfileComponent {
  @Output() changeRecent: EventEmitter<toolEvents> = new EventEmitter();
  @Input() nCaseid: string;
  @Input() ForLinkview: boolean = false;
  @Input() nSectionid: string;
  
  @Input() isPresent: boolean = false;

  recent_list: any = [];

  constructor(private myfileS: MyfileService, private cdr: ChangeDetectorRef) {
  }

  ngOnInit(): void {

  }


  ngOnChanges(changes: SimpleChanges) {
    // if (changes['nSectionid'] && this.nCaseid) {
    //   this.activeFiledata();
    // }
  }

  async activeFiledata() {
    var mdl: recentfileReq = { nCaseid: this.nCaseid, nSectionid: this.nSectionid, cType: this.isPresent ? 'P': 'M'  }
    console.log(mdl)
    const res: recentfileRes[] = await this.myfileS.getrecentfile(mdl);
    this.recent_list = [...res]
    this.cdr.detectChanges();

  }



  async clearRecentFile() {
    var mdl: recentfileReq = { nCaseid: this.nCaseid, nSectionid: this.nSectionid, cType: this.isPresent ? 'P': 'M'}
    const res: boolean = await this.myfileS.clearRecent(mdl);
    if (res)
      this.recent_list = []
    this.cdr.detectChanges();

  }

  changeFile(x) {
    this.changeRecent.emit({ event: 'VIEW', data: x })
  }

}
