import {
  ChangeDetectorRef,
  Component,
  ElementRef,
  EventEmitter,
  Input,
  OnChanges,
  OnInit,
  Output,
  SimpleChanges,
  ViewChild
} from '@angular/core';
import { IconComponent } from '../../icon/icon.component';
import { CommonModule } from '@angular/common';
import { MatMenuModule } from '@angular/material/menu';
import { presentDocType } from '../../../../presentation/interfaces/presentsetup';

@Component({
  selector: 'app-filehader',
  standalone: true,
  imports: [CommonModule, IconComponent, MatMenuModule],
  templateUrl: './filehader.component.html',
  styleUrl: './filehader.component.scss'
})
export class FilehaderComponent implements OnInit, OnChanges {
  @ViewChild('fileheader', { read: ElementRef }) fileHeader: ElementRef;
  @Output() sort: EventEmitter<{}> = new EventEmitter();
  @Output() edit: EventEmitter<any[]> = new EventEmitter();
  @Input() checkoutside: boolean = false;
  @Input() isadmin: boolean = false;
  @Input() SType: string;

  @Input() reqcols: any;

  @Input() presentDocType: presentDocType;
  reqcolKeys = [];
  constructor(private readonly crd: ChangeDetectorRef) {
  }

  ngOnInit(): void {
    this.reqcolKeys = Object.keys(this.reqcols ?? {});
  }

  ngOnChanges(changes: SimpleChanges) {
    this.reqcolKeys = this.customSort(this.reqcols);
  }

  sort_array(key: string, flag: string) {
    this.sort.emit({ key: key, flag: flag });
  }

  editCol(e: unknown, flag?: string) {
    this.edit.emit([e, flag]);
    this.crd.detectChanges();
  }

  customSort(obj: Record<string, unknown> | null | undefined): string[] {
    if (!obj) {
      return [];
    }

    const entries = Object.entries(obj).map(([key, value]) => ({
      key,
      ...(typeof value === 'object' && value !== null ? (value as Record<string, unknown>) : {})
    }));

    // Sort the array based on id order, placing unmatched ones at the end
    entries.sort((a: any, b: any) => (a.order ?? 0) - (b.order ?? 0));
    return entries.map((e: any) => e.key);
  }

  getVisibleColumns(index: number) {
    // Get array of visible columns with their orders
    const visibleColumns = this.reqcolKeys
      .filter(key => this.reqcols?.[key]?.view && this.reqcols?.[key]?.name)
      .map(key => ({
        order: this.reqcols[key].order || 0,
        index: this.reqcolKeys.indexOf(key)
      }));

    // Return index of item with highest order
    const maxOrder = Math.max(...visibleColumns.map(col => col.order));
    return maxOrder == index;
  }
}
